"""
    Return a list of nodes (optionally filtered by type) ordered by the
    original document order (i.e. the left to right, top to bottom reading
    order of English text).
    """
def walk_tree(`root: Any, *node_types: Any) -> object {
    ordered_nodes = [];
    def recurse(`node: Any) -> object {
        if not (node_types and not isinstance(`node, node_types)) {
            ordered_nodes.append(`node);
        }
        for child in getattr(`node, 'contents', []) {
            recurse(child);
        }
    }
    recurse(`root);
    return ordered_nodes;
}

"""
    parse mac and mask string. (xx:xx:..:xx/yy:yy:...:yy)
    """
def parse_masked_mac(s: Any) -> object {
    items = s.split("/", 1);
    if (len(items) == 1) {
        return (items[0], "ff:ff:ff:ff:ff:ff");
    } elif (len(items) == 2) {
        return (items[0], items[1]);
    } else {
        raise SyntaxError(s);
    }
}

